using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings.Teams;
[Authorize(Policy="Permission:Teams.View")]
public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IAuditService audit):PageModel{public IReadOnlyList<Team> Teams{get;private set;}=[];[BindProperty]public string Name{get;set;}="";[BindProperty]public TeamType Type{get;set;}public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid a)return Forbid();Teams=await db.Teams.AsNoTracking().Where(x=>x.AccountId==a&&!x.IsDeleted).OrderBy(x=>x.Name).ToListAsync(ct);return Page();}public async Task<IActionResult>OnPostCreateAsync(CancellationToken ct){if(!await current.HasPermissionAsync("Teams.Manage",ct)||current.AccountId is not Guid a)return Forbid();if(string.IsNullOrWhiteSpace(Name)){ModelState.AddModelError(nameof(Name),"Informe o nome da equipe.");return await OnGetAsync(ct);}var team=new Team{AccountId=a,Name=Name.Trim(),Type=Type};db.Teams.Add(team);await audit.RegisterAsync(current.UserId,"team.created",nameof(Team),team.Id.ToString(),null,new{team.Name,team.Type},null,ct,a);await db.SaveChangesAsync(ct);return RedirectToPage();}}
